"""Reproduce original test geometry and tiny bitmap labels; no external art/fonts."""
from pathlib import Path
import struct,zlib
ROOT=Path(__file__).parent/'images'
ROOT.mkdir(exist_ok=True)
def png(name,p):
 h,w=len(p),len(p[0])
 def chunk(k,d):return struct.pack('>I',len(d))+k+d+struct.pack('>I',zlib.crc32(k+d)&0xffffffff)
 raw=b''.join(b'\0'+bytes(v for px in row for v in px) for row in p)
 (ROOT/(name+'.png')).write_bytes(b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',w,h,8,6,0,0,0))+chunk(b'IDAT',zlib.compress(raw))+chunk(b'IEND',b''))
def canvas(w,h,c=(0,0,0,0)):return [[c]*w for _ in range(h)]
def rect(p,x0,y0,x1,y1,c):
 for y in range(max(0,y0),min(len(p),y1)):
  for x in range(max(0,x0),min(len(p[0]),x1)):p[y][x]=c
p=canvas(52,52,(39,49,59,255));rect(p,2,2,50,50,(21,29,36,255));png('slot',p)
p=canvas(52,52);rect(p,0,0,52,2,(255,255,255,255));rect(p,0,50,52,52,(255,255,255,255));rect(p,0,0,2,52,(255,255,255,255));rect(p,50,0,52,52,(255,255,255,255));png('frame',p)
for item in ['herb','ore','sword','helmet','armor','boots','dummy']:
 p=canvas(48,48)
 if item=='herb':
  rect(p,22,12,26,40,(62,145,74,255));rect(p,10,13,23,24,(101,206,94,255));rect(p,26,21,40,32,(77,180,102,255))
 elif item=='ore':
  for y in range(9,40):
   for x in range(7,42):
    if abs(x-24)+abs(y-24)<20:p[y][x]=(150,168,190,255) if x<24 else (101,120,150,255)
 elif item=='sword':
  rect(p,21,4,27,31,(220,230,238,255));rect(p,12,30,36,35,(187,139,67,255));rect(p,21,35,27,46,(119,78,45,255))
 elif item=='helmet':
  rect(p,8,14,40,35,(177,192,204,255));rect(p,13,8,35,20,(177,192,204,255));rect(p,13,24,35,30,(44,56,69,255))
 elif item=='armor':
  rect(p,13,10,35,41,(97,143,190,255));rect(p,5,12,13,26,(134,176,210,255));rect(p,35,12,43,26,(134,176,210,255));rect(p,20,8,28,15,(40,53,70,255))
 elif item=='boots':
  rect(p,8,8,20,34,(183,124,70,255));rect(p,8,30,25,41,(139,88,48,255));rect(p,28,8,40,34,(183,124,70,255));rect(p,28,30,46,41,(139,88,48,255))
 else:
  rect(p,20,6,28,46,(160,116,61,255));rect(p,5,13,43,21,(160,116,61,255));rect(p,16,2,32,14,(202,168,110,255))
 png(item,p)
p=canvas(16,16);rect(p,5,1,11,7,(240,196,150,255));rect(p,4,7,12,12,(63,167,203,255));rect(p,5,12,7,16,(38,50,72,255));rect(p,9,12,11,16,(38,50,72,255));png('player',p)
png('bar',canvas(12,14,(255,255,255,255)))
p=canvas(192,36,(36,62,48,255))
for y in range(36):
 for x in range(192):
  if x%10==0 or y%10==0:p[y][x]=(43,72,55,255)
png('floor',p)
